"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2499],{2842(e){e.exports=JSON.parse('{"title":"\uc5b4\ub5bb\uac8c \ud14c\uc2a4\ud2b8\ud574\uc57c \ud558\ub294\uac00?","date":"2024-05-29","coverUrl":null,"html":"<h2 data-notion-block-id=\\"0ce60598-b569-4edf-8340-e3fb67be0974\\" id=\\"0ce60598-b569-4edf-8340-e3fb67be0974\\">\uc5b4\ub5bb\uac8c \ud14c\uc2a4\ud2b8\ud574\uc57c \ud558\ub294\uac00?</h2><a href=\\"https://kentcdodds.com/blog/how-to-know-what-to-test\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kentcdodds.com/blog/how-to-know-what-to-test</a><a href=\\"https://kentcdodds.com/blog/write-tests\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kentcdodds.com/blog/write-tests</a><p data-notion-block-id=\\"12a7a376-1f96-46a5-8ece-9c6f0586d898\\"><a href=\\"https://soojae.tistory.com/83\\">(\uccab \uae00\uc758 \ud55c\uad6d\uc5b4 \ubc88\uc5ed)</a></p><p data-notion-block-id=\\"62f69023-7df4-46b7-b109-829a0b817eba\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://techblog.woowahan.com/17404/\\">\ucf54\ub4dc\uc640 \ud568\uaed8 \uc54c\uc544\ubcf4\ub294 \ud504\ub860\ud2b8\uc5d4\ub4dc \ub2e8\uc704\ud14c\uc2a4\ud2b8</a> \uae00\uc744 \ubcf4\uace0 \ub5a0\uc624\ub978 \uae00\ub4e4\uc785\ub2c8\ub2e4. \uc6d0\uce59\ubcf4\ub2e4\ub294, \uc5b4\ub5a4 \ud14c\uc2a4\ud2b8\ub97c \uc791\uc131\ud574\uc57c \ud558\ub294\uc9c0\ub97c \uc0dd\uac01\ud558\ub294\uac8c \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c, <a href=\\"https://kentcdodds.com/blog/static-vs-unit-vs-integration-vs-e2e-tests\\">\ud14c\uc2a4\ud305 \ud2b8\ub85c\ud53c</a>\ub97c \ub9cc\ub4e0 Kent D dodds\uc758 \uc0dd\uac01\uc774 \ub4dc\ub7ec\ub098\ub294 \uae00\uc744 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \ub9d0\ud558\uba74 \ud14c\uc2a4\ud2b8\ub97c \uc791\uc131\ud560 \ub54c \uad6c\ud604\uc744 \ubc14\uafb8\uc9c0 \uc54a\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud558\uc9c0 \ub9d0\uace0 \ub098\uc758 \ub3d9\uc791\uc758 \uc218\ub3d9 \ud14c\uc2a4\ud2b8\ub97c \ub300\uccb4\ud558\uae30 \uc704\ud574 \uc791\uc131\ud558\ub77c\ub294 \uc8fc\uc7a5\uc774\uba70, \uc774\ub97c \uc5ec\ub7ec\uac00\uc9c0 \ucf54\ub4dc\uc640 \ud568\uaed8 \uac00\uc838\uc640\uc11c \uc124\uba85\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ec52b76b-2edc-46da-87c7-91c0e24f936b\\" id=\\"ec52b76b-2edc-46da-87c7-91c0e24f936b\\">throttle\uc5d0\uc11c useDeferredValue\ub85c</h2><a href=\\"https://www.joshwcomeau.com/react/use-deferred-value/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/react/use-deferred-value/</a><p data-notion-block-id=\\"817f5b34-ac42-4143-b575-c8d52b716772\\"><b>\uc2ec\uc724\uc12d</b>: React\uc5d0\uc11c \ub9c8\uc9c0\ub9c9 Input \uac12\uc744 \uc54c\uc544\ub0b4\uae30 \uc704\ud574\uc11c <a href=\\"https://css-tricks.com/debouncing-throttling-explained-examples/\\">Throttle\uacfc Debounce</a>\uc758 \uac1c\ub150\uc744 \uc54c\uace0 \uc788\uc5b4\uc57c \ud588\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774 \ub458\uc740 React \ub80c\ub354\ub9c1\uacfc \ubcc4\uac1c\ub85c \ub85c\uc9c1\uc774 \ub3cc\uc544\uac00\uc11c React \ub80c\ub354\ub9c1\uc774 \ube68\ub9ac \ub05d\ub098\ub3c4 delay\ub9cc\ud07c \uae30\ub2e4\ub824\uc57c \ud588\uc2b5\ub2c8\ub2e4. \uc774\uc81c\ub294 18\ubc84\uc804\uc5d0 \ub4e4\uc5b4\uc628  <code>useDeferredValue</code>\ub85c React\uc5d0\uc11c Throttle\uc744 \ucc98\ub9ac\ud558\ub3c4\ub85d \ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"9ee9b8b4-94a5-48c2-b795-2c70ea08a65e\\"><b>\uae40\ub300\uad00</b>: \uae30\uc874 Throttle\uc774\ub098 Debounce\uc640 \ub2ec\ub9ac, React\uc758 \ub80c\ub354\ub9c1 \uc0ac\uc774\ud074\uacfc \uc790\uc5f0\uc2a4\ub7fd\uac8c \ud1b5\ud569\ub418\uc5b4 \uac12 \uc5c5\ub370\uc774\ud2b8\uc758 \uc6b0\uc120\uc21c\uc704\ub97c \ub0ae\ucdb0\uc11c \uc131\ub2a5 \ucd5c\uc801\ud654(\ud639\uc740 FPS \ub4dc\ub86d \ubc29\uc9c0)\uac00 \uac00\ub2a5\ud574\uc84c\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2a1c391e-d90f-4ec8-b3c6-ad9e5c3b1bc7\\" id=\\"2a1c391e-d90f-4ec8-b3c6-ad9e5c3b1bc7\\">NextJS\uc640 SSRF \ucde8\uc57d\uc810</h2><a href=\\"https://www.assetnote.io/resources/research/digging-for-ssrf-in-nextjs-apps\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.assetnote.io/resources/research/digging-for-ssrf-in-nextjs-apps</a><p data-notion-block-id=\\"cd9324e4-fd03-4d35-8672-ab962b384a38\\"><b>\uc2ec\uc724\uc12d</b>: NextJS\uc5d0\uc11c SSRF \ucde8\uc57d\uc810\uc774 \uc788\uc5c8\uace0 14.1.1 \ubc84\uc804\uc5d0\uc11c \ud328\uce58\ub418\uc5c8\ub2e4\ub294 \ub0b4\uc6a9\uc785\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc\ub97c \uc704\ud574 \uc11c\ubc84\ub97c \uad00\ub9ac\ud560 \uc218\ub3c4 \uc788\uae30 \ub54c\ubb38\uc5d0 \ud074\ub77c\uc774\uc5b8\ud2b8 \uce21 \uc704\uc870\ub294 \ud56d\uc0c1 \uac80\uc99d\ud574\uc57c \ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ubcf4\uc548 \ud504\ub85c\uc81d\ud2b8\uc778 OWASP\uc5d0\uc11c <a href=\\"https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html\\">SSRF \uce58\ud2b8\uc2dc\ud2b8</a>\ub97c \uc81c\uacf5\ud558\uace0 \uc788\uc73c\ub2c8 \ud55c\ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5a7bf5b1-8971-4ad9-a829-028b3b4f8d97\\" id=\\"5a7bf5b1-8971-4ad9-a829-028b3b4f8d97\\">\ud14d\uc2a4\ud2b8 \ud655\ub300\uacfc \uc6f9 \uc811\uadfc\uc131</h2><a href=\\"https://medium.com/airbnb-engineering/rethinking-text-resizing-on-web-1047b12d2881\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/airbnb-engineering/rethinking-text-resizing-on-web-1047b12d2881</a><p data-notion-block-id=\\"ed0f3b33-6f7c-4597-bf7c-7ee3cc61e51e\\"><b>\uc2ec\uc724\uc12d</b>: \ub178\uc548\uc744 \uc628 \uc0ac\ub78c\ub4e4\uc744 \uc704\ud574 \ube0c\ub77c\uc6b0\uc800\uc758 \ud655\ub300 \ube44\uc728\uc744 \ub192\uc774\ub294 \uc0ac\ub78c\uc740 \ub9ce\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc77c\ubc18\uc801\uc778 \uc6f9 \uc0ac\uc774\ud2b8\ub97c \ub9cc\ub4e4 \ub54c \uace0\ub824\ud558\ub294 \uc0ac\ub78c\uc740 \ub9ce\uc9c0 \uc54a\uc8e0. \uadf8\ub798\uc11c \uc9c0\uc6d0\ud558\ub294 \uac83\uc744 \ud68c\uc0ac\ubc94\uc704\ub85c \ud655\ub300\ud558\uae30 \uc704\ud574 \uc5b4\ub5bb\uac8c \ud234\uc744 \uc0ac\uc6a9\ud588\ub294\uc9c0 \uc548\ub0b4\ud569\ub2c8\ub2e4. \uc6f9 \uc811\uadfc\uc131\uc744 \uc704\ud574 rem\uc744 \uc0ac\uc6a9\ud558\ub77c\ub294 \uc0ac\ub78c\uc740 \ub9ce\uc9c0\ub9cc \ud604\uc2e4\uc801\uc778 \ub300\uc548\uc744 \ub0b4\ub193\uc9c0 \uc54a\ub294 \uae00\uc774 \ub300\ubd80\ubd84\uc778\ub370 \uad6c\uccb4\uc801\uc778 \ubc29\ubc95\uacfc \ud568\uaed8 \uc18c\uac1c\ud574\uc11c \uc77c\ubd80\ub294 \ud68c\uc0ac\uc5d0 \ub9de\uac8c \ubc14\uafd4\uc11c \uc801\uc6a9\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"33710ab4-f781-493a-aaf6-1812739d7fd9\\" id=\\"33710ab4-f781-493a-aaf6-1812739d7fd9\\"><code>contrast-color()</code>\uc5d0 \ub300\ud55c \uc0dd\uac01\ub4e4</h2><a href=\\"https://lea.verou.me/blog/2024/contrast-color/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lea.verou.me/blog/2024/contrast-color/</a><a href=\\"https://ericwbailey.website/published/contrast-color-is-a-good-thing-but-also-solving-the-problem-at-the-wrong-layer/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ericwbailey.website/published/contrast-color-is-a-good-thing-but-also-solving-the-problem-at-the-wrong-layer/</a><p data-notion-block-id=\\"ef7d3891-3384-4b35-b4f7-d8eab49844f9\\"><b>\uc2ec\uc724\uc12d</b>: \uccab \uae00\uc740 <code>contrast-color()</code>\uc744 \uc18c\uac1c\ud558\uace0, \uc544\uc9c1 \uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294 \ube0c\ub77c\uc6b0\uc800\ub97c \uc704\ud574 Relative Color Syntax\ub97c \uc0ac\uc6a9\ud574\uc11c \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \uc124\uba85\ud569\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 <code>contrast-color()</code>\uc774 \uc6f9 \uac1c\ubc1c\uc790\uac00 \uc811\uadfc\ud558\uae30 \uc26c\uc6b4 \ubc29\ubc95\uc774\uc9c0\ub9cc \ubcf4\ud3b8\uc801\uc778 \uc6f9 \uc811\uadfc\uc131\uc744 \uc704\ud574 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc9c0\uc6d0\ud574\uc57c \ud55c\ub2e4\uace0 \uc8fc\uc7a5\ud569\ub2c8\ub2e4. \uac1c\ubc1c\uc790\ub4e4\uc5d0\uac8c \uc2e0 \uae30\uc220\uc774 \ub3c4\ub2ec\ud558\ub824\uba74 \uc2dc\uac04\uc774 \uac78\ub9ac\uae30 \ub54c\ubb38\uc5d0(<a href=\\"https://frontendmasters.com/blog/weve-got-container-queries-now-but-are-we-actually-using-them/\\">\uc9c0\uae08 \ucee8\ud14c\uc774\ub108 \ucffc\ub9ac\ub97c \uc0ac\uc6a9\ud558\uace0 \uc788\ub098\uc694?</a>), \uc774\ub7f0 \uae30\uc220\uc744 \uc5b4\ub5bb\uac8c \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc811\uadfc\ud574\uc57c \ud560\uc9c0 \ub9ce\uc740 \uace0\ubbfc\uc774 \ub429\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f189f29c-b627-4903-8168-646cd9168b7e\\" id=\\"f189f29c-b627-4903-8168-646cd9168b7e\\">\uc778\ub77c\uc778 \uc2a4\ud0c0\uc77c\uc744 \ud65c\uc6a9\ud55c CSS Hooks</h2><a href=\\"https://weser.io/blog/inline-styles-on-steroids\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://weser.io/blog/inline-styles-on-steroids</a><p data-notion-block-id=\\"b3b56360-6a24-4bc8-85eb-f7fa118ddf32\\"><b>\uc2ec\uc724\uc12d</b>: \uc778\ub77c\uc778 \uc2a4\ud0c0\uc77c\uc744 \ud65c\uc6a9\ud55c CSS-in-JS \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 CSS hooks\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. CSS Hooks\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/e118a44c46de44b79492998633298d32#e4fc7fe7-d3e6-4687-8650-841e73f19b67\\">CSS \ud2b8\ub9ac\uc640 DOM \ud2b8\ub9ac\uac00 \ub2e4\ub978 \uc704\uce58\uc5d0 \uc788\ub294 \uac83\uc740 \ubb38\uc81c\uac00 \ub41c\ub2e4</a>\uc640 \ube44\uc2b7\ud55c \uc811\uadfc \ubc29\uc2dd\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#c0d8616e-52c1-482b-8471-6505d70f30e3\\">CSS Inlining\uc758 \uc131\ub2a5 \ud5a5\uc0c1</a>\uc5d0\uc11c \uc18c\uac1c\ud588\ub2e4\uc2dc\ud53c \uc131\ub2a5\uc5d0 \uc774\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub124\uc774\ud2f0\ube0c CSS \uae30\ub2a5\ub4e4\uc744 \uc4f0\ub824\uba74 \uc544\uc9c1\uc774\ub77c\ub294 \uc810\uc774 \uc544\uc27d\ub124\uc694.</p><h2 data-notion-block-id=\\"03637a37-a07c-4a5f-9684-40ba0b57a1c9\\" id=\\"03637a37-a07c-4a5f-9684-40ba0b57a1c9\\">SSR\uc5d0\uc11c Styled Components\ub294 \uc9c4\uc9dc \ub290\ub9ac\ub2e4.</h2><a href=\\"https://blog.levineandrew.com/quantifying-the-impact-of-styled-components-on-server-response-times\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.levineandrew.com/quantifying-the-impact-of-styled-components-on-server-response-times</a><p data-notion-block-id=\\"87b55360-b546-4942-a26b-4c272d957c23\\">\uc800\uc790\uac00 styled-components\uac00 SSR \uc694\uccad \uc911\uc5d0\uc11c \ub9e4\uc6b0 \ud070 \uc601\uc5ed\uc744 \ucc28\uc9c0\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uace0 \uc2e4\uc81c \ubd84\uc11d\uc744 \ud1b5\ud574 \uc99d\uba85\ud574\ub0b8 \uae00\uc785\ub2c8\ub2e4. Node.js\ub97c \ubd84\uc11d\ud558\ub294 \ubc29\uc2dd\uacfc \ub77c\uc774\ube0c\ub7ec\ub9ac \ud074\ub860\uc744 \ud1b5\ud574 \uc99d\uba85\ud558\ub294 \ubd80\ubd84\uc740 \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc73c\ub2c8 \uc811\uadfc\ubc95\uc744 \uc54c\uc544 \ub458 \ud544\uc694\ub294 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"dd840bd1-cc48-40c2-9715-0b840c1b6ade\\" id=\\"dd840bd1-cc48-40c2-9715-0b840c1b6ade\\">UI \ubc00\ub3c4\uc5d0 \ub300\ud55c \uc0dd\uac01</h2><a href=\\"https://matthewstrom.com/writing/ui-density/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://matthewstrom.com/writing/ui-density/</a><p data-notion-block-id=\\"132024ce-a069-4e01-981e-13bc3c2f7bf3\\">\uc800\uc790\uac00 \ub9d0\ud588\ub4ef\uc774, \ub514\uc790\uc778\uc774 \uc88b\uace0 \ub098\uc05c\uc9c0\ub294 \ub9e4\uc6b0 \uc8fc\uad00\uc801\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub514\uc790\uc778\uc740 \uc77c\uad00\uc801\uc774\uc5ec\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uc704\ud574 \uc800\uc790\ub294 \uc5ec\ub7ec\uac00\uc9c0 \uc9c0\ud45c\ub97c \uc815\uc758\ud558\uace0 \uc5b4\ub5bb\uac8c \ub17c\uc758\ud574\uc57c \ud560\uc9c0 \uc0dd\uac01\ud560 \uac70\ub9ac\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4(\uac00\uc7a5 \uc27d\uac8c \uc811\uadfc\ud560 \uc218 \uc788\ub294 \uc2dc\uac04 \ubc00\ub3c4\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc5b8\uae09\ud569\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"51b90ea1-085b-4ae8-b337-2863581efaba\\" id=\\"51b90ea1-085b-4ae8-b337-2863581efaba\\">\uc6f9 \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8 \ub3c4\uad6c</h2><a href=\\"https://www.a11y-collective.com/design/accessibility-testing-tools/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.a11y-collective.com/design/accessibility-testing-tools/</a><p data-notion-block-id=\\"5f79aa85-6769-4db5-9163-c18e7e06d554\\">\uc0dd\uc18c\ud55c \uc6f9 \uc811\uadfc\uc131 \ud14c\uc2a4\ud2b8 \ub3c4\uad6c\ub4e4\uc744 \uc18c\uac1c\ud574\uc90d\ub2c8\ub2e4. \uc218\ub3d9\uc73c\ub85c \ud14c\uc2a4\ud2b8\ud558\ub294 \uac83\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc \ud56d\uc0c1 \uc218\ub3d9 \ud14c\uc2a4\ud2b8\ub85c \uc2dc\uac04\uc744 \uc3df\uc744 \uc218\ub294 \uc5c6\uc73c\ub2c8\uae4c\uc694.</p><h2 data-notion-block-id=\\"1644609c-67ff-44b8-b782-1c27a010d462\\" id=\\"1644609c-67ff-44b8-b782-1c27a010d462\\">SolidStart 1.0, Angluar 18 \ucd9c\uc2dc</h2><a href=\\"https://www.solidjs.com/blog/solid-start-the-shape-frameworks-to-come\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.solidjs.com/blog/solid-start-the-shape-frameworks-to-come</a><a href=\\"https://blog.angular.dev/angular-v18-is-now-available-e79d5ac0affe\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.angular.dev/angular-v18-is-now-available-e79d5ac0affe</a><p data-notion-block-id=\\"75cd2dda-b2be-4970-930d-63e51efed794\\">Zone.js(Angular\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ubcc0\uacbd \ud0d0\uc9c0 \ub9e4\ucee4\ub2c8\uc998, \uc790\uc138\ud55c \uac74 <a href=\\"https://blog.thoughtram.io/angular/2016/02/01/zones-in-angular-2.html\\">Zone.js in Angular</a> / <a href=\\"https://norux.me/64\\">(\ubc88\uc5ed)</a>\ub97c \ucc38\uc870\ud558\uc138\uc694!)\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4dc\ub97c \ub123\uc740 Angular 18 \ubc84\uc804(\uc774\uc678\uc5d0\ub3c4 \ub9ce\uc740 \ud328\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4)\uacfc <a href=\\"https://vinxi.vercel.app/\\">Vinxi</a>(Vite, Nitro \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 meta framework \uc720\ud2f8\ub9ac\ud2f0)\ub97c \uae30\ubc18\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc9c4 SolidStart\uac00 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9ac34198-bcf7-4ba6-939b-f3eaef236a8c\\" id=\\"9ac34198-bcf7-4ba6-939b-f3eaef236a8c\\">JSX \uc548\uc5d0\uc11c \uc870\uac74\uc744 \uad00\ub9ac\ud558\uc9c0 \ub9d0\uace0, \ucd5c\uc0c1\ub2e8\uc5d0\uc11c \uad00\ub9ac\ud558\uc138\uc694.</h2><a href=\\"https://kyleshevlin.com/prefer-multiple-compositions/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kyleshevlin.com/prefer-multiple-compositions/</a><p data-notion-block-id=\\"99331ff7-eee0-481d-ab3b-af601ae53b3a\\">\uc800\uc790\uac00 \uc870\uac74\ubd80\uc5d0 \ub300\ud574 \uc0c8\ub85c\uc6b4 \uad00\uc810\uc744 \uc81c\uc2dc\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ud55c \uac12\uc774 enum\ud615\uc2dd\uc744 \ub748\ub2e4\uba74 \uc88b\uc740 \uc811\uadfc \ubc29\uc2dd\uc77c \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"129965d8-e8d9-4db6-ad90-a63c90e658c1\\"></p>"}')}}]);